params.command:
$ErrorActionPreference='Continue'
$repo='C:\Users\Xxkan\mhw-safe-branch-delete2'
git -C $repo fetch origin --prune | Out-Host
$targets=@('agent/agent-control-federation-heartbeat-20260929','agent/archive-streaming-budget-20260928','agent/heaven-hosted-runner-diagnose-20260929','agent/liveness-scheduler-machine-policy-20260929','agent/smart-pack-planner-core','agent/updater-cross-session-ownership-20260929','agent/updater-existing-release-rest-ref-20260928','agent/updater-existing-release-rest-ref-gate-20260928','agent/updater-existing-release-rest-ref-gate2-20260928','agent/windows-live-containment-hardening','agent/windows-live-containment-hardening-v2','feature/agent-control-plane-v2-20260928','integration/smart-pack-planner-main-20260929')
$deleted=@();$missing=@();$failed=@()
foreach($b in $targets){
  git -C $repo show-ref --verify --quiet ("refs/remotes/origin/"+$b)
  if($LASTEXITCODE -ne 0){$missing+=$b;continue}
  & git -C $repo push origin --delete $b 2>&1 | Out-Host
  if($LASTEXITCODE -eq 0){$deleted+=$b}else{$failed+=$b}
}
git -C $repo fetch origin --prune | Out-Null
[pscustomobject]@{deleted=$deleted;deleted_count=$deleted.Count;missing=$missing;failed=$failed;main=(git -C $repo rev-parse origin/main).Trim()} | ConvertTo-Json -Depth 4
